svg.script:
//!export-start
let _pb_state = false;
let _ps_label = 'START';
let _pc_on = '#30d158';
let _pc_off = '#2e333a';
//!export-end

function postValue(id, value) {
  console.error('Not defined!', id, value);
}

let currentState = !!_pb_state;

function mixColor(hex, amount) {
  const clean = String(hex || '').replace('#', '').padEnd(6, '0').slice(0, 6);
  const num = parseInt(clean, 16);
  const clamp = value => Math.max(0, Math.min(255, value));
  const r = clamp((num >> 16) + amount);
  const g = clamp(((num >> 8) & 255) + amount);
  const b = clamp((num & 255) + amount);
  return '#' + [r, g, b].map(v => v.toString(16).padStart(2, '0')).join('');
}

function setText(el, text) {
  if (!el) return;
  while (el.firstChild) {
    el.removeChild(el.firstChild);
  }
  el.appendChild(document.createTextNode(text));
}

function render() {
  const face = document.getElementById('buttonFace');
  const glow = document.getElementById('outerGlow');
  const icon = document.getElementById('playIcon');
  const label = document.getElementById('label');
  const activeColor = currentState ? _pc_on : _pc_off;

  if (face) face.setAttribute('fill', 'url(#bezelShadow)');
  if (face) face.setAttribute('fill', mixColor(activeColor, currentState ? -28 : -10));
  if (glow) {
    glow.setAttribute('fill', _pc_on);
    glow.setAttribute('opacity', currentState ? '0.68' : '0.14');
  }
  if (icon) icon.setAttribute('fill', currentState ? '#f4fff7' : '#c7cdd5');
  setText(label, _ps_label || 'START');
  if (label) label.setAttribute('fill', currentState ? '#ecfff1' : '#d7dde6');
}

function putValue(id, value) {
  if (id === '_pb_state') {
    currentState = !!value;
    render();
  } else if (id === '_ps_label') {
    _ps_label = String(value ?? '');
    render();
  } else if (id === '_pc_on') {
    _pc_on = String(value ?? '#30d158');
    render();
  } else if (id === '_pc_off') {
    _pc_off = String(value ?? '#2e333a');
    render();
  }
}

function toggleValue() {
  currentState = !currentState;
  render();
  if (typeof postValue === 'function') {
    postValue('_pb_state', currentState);
  }
}

const target = document.getElementById('clickTarget');
if (target) {
  target.addEventListener('click', toggleValue);
  target.style.cursor = 'pointer';
}

render();
